ALTER TABLE invitations ADD COLUMN visibility ENUM('public','password','private') NOT NULL DEFAULT 'public' AFTER status, ADD COLUMN access_password_hash VARCHAR(255) NULL AFTER visibility, ADD COLUMN share_media_id BIGINT UNSIGNED NULL AFTER access_password_hash, ADD KEY idx_invitation_visibility(church_id,visibility,status), ADD CONSTRAINT fk_invitation_share_media FOREIGN KEY(share_media_id) REFERENCES invitation_media(id) ON DELETE SET NULL;
CREATE TABLE invitation_access_failures(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,church_id BIGINT UNSIGNED NOT NULL,invitation_id BIGINT UNSIGNED NOT NULL,attempted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ip_hash CHAR(64) NULL,KEY idx_access_failures_tenant(church_id,invitation_id,attempted_at),CONSTRAINT fk_access_failure_church FOREIGN KEY(church_id) REFERENCES churches(id) ON DELETE CASCADE,CONSTRAINT fk_access_failure_invitation FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
